import{_ as t,a as o,b as a,c as r}from"./chunks/21.HqmV-2N6.js";import{_ as s,o as i,c as n,a0 as l}from"./chunks/framework.DRjqbEpm.js";const y=JSON.parse('{"title":"🧠 Adaptive Engine","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/adaptive-engine.md","filePath":"en/guide/adaptive-engine.md"}'),d={name:"en/guide/adaptive-engine.md"};function h(c,e,p,u,g,b){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="🧠-adaptive-engine" tabindex="-1">🧠 Adaptive Engine <a class="header-anchor" href="#🧠-adaptive-engine" aria-label="Permalink to &quot;🧠 Adaptive Engine&quot;">​</a></h1><blockquote><p>Teach V-Train how to find video thumbnails on any website!</p></blockquote><hr><h2 id="_1-what-is-the-adaptive-engine" tabindex="-1">1. What is the Adaptive Engine? <a class="header-anchor" href="#_1-what-is-the-adaptive-engine" aria-label="Permalink to &quot;1. What is the Adaptive Engine?&quot;">​</a></h2><p>V-Train supports popular video websites automatically. But there are many other video websites on the internet. V-Train cannot know all of them.</p><p>The <strong>Adaptive Engine</strong> lets <strong>YOU</strong> create the rules for these websites:</p><ul><li>🖱️ Right-click on a video thumbnail.</li><li>🔲 Use a box to select the thumbnail.</li><li>🔗 Paste a video link and click the Video ID.</li><li>💾 Save the rule. V-Train will now work on this website!</li></ul><p>You do not need to write any code. It only takes about <strong>30 seconds to 2 minutes</strong>.</p><div class="info custom-block"><p class="custom-block-title">💡 Example</p><p>Imagine V-Train is a new worker. V-Train does not know what this website looks like. You must show V-Train where the video thumbnails are. Train it once, and V-Train will remember forever.</p></div><hr><h2 id="_2-important-switch-to-monitoring-mode-first" tabindex="-1">2. Important: Switch to &quot;Monitoring&quot; Mode First <a class="header-anchor" href="#_2-important-switch-to-monitoring-mode-first" aria-label="Permalink to &quot;2. Important: Switch to &quot;Monitoring&quot; Mode First&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">⚠️ You must use Monitoring Mode</p><p>The Adaptive Engine does not work in &quot;Monitoring Off&quot; mode.</p><p>If you use &quot;Monitoring Off&quot; and click &quot;Start Training Engine&quot;, you will see a red error message.</p><p><strong>Please open the V-Train Dashboard → Turn on &quot;Monitoring&quot; → Try again.</strong></p></div><p>Why? &quot;Monitoring Off&quot; mode stops V-Train from adding things to the screen. V-Train needs to add a selection box to the screen for training.</p><hr><h2 id="_3-training-steps-🗺️" tabindex="-1">3. Training Steps 🗺️ <a class="header-anchor" href="#_3-training-steps-🗺️" aria-label="Permalink to &quot;3. Training Steps 🗺️&quot;">​</a></h2><p>There are six steps to train V-Train:</p><h3 id="step-1-right-click-to-start-training" tabindex="-1">Step 1: Right-click to start training <a class="header-anchor" href="#step-1-right-click-to-start-training" aria-label="Permalink to &quot;Step 1: Right-click to start training&quot;">​</a></h3><p>Right-click on <strong>ANY video thumbnail</strong>. Click this option in the menu:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>V-Train: Start Training Engine</span></span></code></pre></div><blockquote><p><img src="'+t+'" alt="Right-click menu"></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Quick Tip</p><p>You can right-click anywhere on the video picture. It does not need to be perfect. You can adjust it later.</p></div><h3 id="step-2-the-selection-box-appears" tabindex="-1">Step 2: The selection box appears <a class="header-anchor" href="#step-2-the-selection-box-appears" aria-label="Permalink to &quot;Step 2: The selection box appears&quot;">​</a></h3><p>The page is now in &quot;Training Mode&quot;:</p><ul><li>Old V-Train progress bars become clear.</li><li>A <strong>colored box</strong> appears where you right-clicked.</li></ul><blockquote><p><img src="'+o+'" alt="Training selection box overlay"></p></blockquote><h3 id="step-3-use-the-keyboard-to-adjust-the-box" tabindex="-1">Step 3: Use the keyboard to adjust the box <a class="header-anchor" href="#step-3-use-the-keyboard-to-adjust-the-box" aria-label="Permalink to &quot;Step 3: Use the keyboard to adjust the box&quot;">​</a></h3><p>The color of the box shows if the selection is correct:</p><table tabindex="0"><thead><tr><th>Color</th><th>Meaning</th></tr></thead><tbody><tr><td>🔵 <strong>Cyan (Blue)</strong></td><td>✅ Good target. You can press Enter.</td></tr><tr><td>🔴 <strong>Red</strong></td><td>❌ Bad target. You need to adjust it.</td></tr></tbody></table><p>A label is in the top right corner of the box:</p><ul><li>Green background with <strong>VALID</strong> → You can press Enter.</li><li>Red background with an error message → You must move the box.</li></ul><p><strong>Use the keyboard to move the box:</strong></p><ul><li><code>↑</code> Move up (Makes the box larger)</li><li><code>↓</code> Move down (Makes the box smaller)</li></ul><blockquote><p><img src="'+a+'" alt="Selection box color explanation"></p></blockquote><h3 id="step-4-press-enter-to-confirm" tabindex="-1">Step 4: Press Enter to confirm <a class="header-anchor" href="#step-4-press-enter-to-confirm" aria-label="Permalink to &quot;Step 4: Press Enter to confirm&quot;">​</a></h3><p>When the box is cyan and says <strong>VALID</strong>, press <code>Enter</code>.</p><p>The system will create a rule to find all similar thumbnails on the page.</p><h3 id="step-5-select-the-video-id" tabindex="-1">Step 5: Select the Video ID <a class="header-anchor" href="#step-5-select-the-video-id" aria-label="Permalink to &quot;Step 5: Select the Video ID&quot;">​</a></h3><p>A <strong>panel</strong> will appear on the screen:</p><ol><li>Paste a <strong>full video link</strong> into the top box. (Copy it from your browser address bar).</li><li>The system splits the link into parts.</li><li><strong>Click</strong> the part that is the &quot;Video ID&quot;.</li></ol><blockquote><p><img src="'+r+`" alt="URL dissection panel"></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Use the correct link</p><p>You <strong>must</strong> paste the link for the video you just right-clicked. If you right-clicked Video A, you must paste the link for Video A.</p></div><h3 id="step-6-choose-a-slot-and-save" tabindex="-1">Step 6: Choose a slot and save <a class="header-anchor" href="#step-6-choose-a-slot-and-save" aria-label="Permalink to &quot;Step 6: Choose a slot and save&quot;">​</a></h3><p>Click the ID part. Then, choose a <strong>Save Slot (Mod 1 to Mod 4)</strong> and click Save.</p><p>Training is finished! Refresh the page. V-Train will now work on this website.</p><hr><h2 id="_4-why-is-the-box-red-🎨" tabindex="-1">4. Why is the Box Red? 🎨 <a class="header-anchor" href="#_4-why-is-the-box-red-🎨" aria-label="Permalink to &quot;4. Why is the Box Red? 🎨&quot;">​</a></h2><h3 id="✅-cyan-valid" tabindex="-1">✅ Cyan (VALID) <a class="header-anchor" href="#✅-cyan-valid" aria-label="Permalink to &quot;✅ Cyan (VALID)&quot;">​</a></h3><p>A cyan box is good. You can press Enter.</p><h3 id="❌-reasons-for-a-red-box-invalid" tabindex="-1">❌ Reasons for a Red Box (INVALID) <a class="header-anchor" href="#❌-reasons-for-a-red-box-invalid" aria-label="Permalink to &quot;❌ Reasons for a Red Box (INVALID)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Reason</th><th>Explanation</th><th>How to Fix</th></tr></thead><tbody><tr><td><strong>Selected <code>&lt;img&gt;</code> or <code>&lt;picture&gt;</code></strong></td><td>You selected the picture itself.</td><td>Press <code>↑</code> to make the box larger.</td></tr><tr><td><strong>Selected <code>&lt;video&gt;</code></strong></td><td>You selected the video player.</td><td>Press <code>↑</code> to make the box larger.</td></tr><tr><td><strong>Selected <code>&lt;svg&gt;</code> or <code>&lt;canvas&gt;</code></strong></td><td>You selected a graphic.</td><td>Press <code>↑</code> to make the box larger.</td></tr><tr><td><strong>Element too small</strong></td><td>You selected a small icon.</td><td>Press <code>↑</code> to make the box larger.</td></tr><tr><td><strong>Element already tracked</strong></td><td>V-Train already knows this rule.</td><td>You do not need to train it.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Most common mistake</p><p>Many people right-click the picture, and the box stays red. Remember: you must select the <strong>box that holds the picture</strong>, not the picture itself. Just press <code>↑</code> one or two times.</p></div><hr><h2 id="_5-keyboard-shortcuts-⌨️" tabindex="-1">5. Keyboard Shortcuts ⌨️ <a class="header-anchor" href="#_5-keyboard-shortcuts-⌨️" aria-label="Permalink to &quot;5. Keyboard Shortcuts ⌨️&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Function</th></tr></thead><tbody><tr><td><code>↑</code> Up Arrow</td><td>Make the box <strong>larger</strong> (Select Parent)</td></tr><tr><td><code>↓</code> Down Arrow</td><td>Make the box <strong>smaller</strong> (Select Child)</td></tr><tr><td><code>Enter</code></td><td>Confirm selection</td></tr><tr><td><code>Esc</code></td><td>Cancel training</td></tr></tbody></table><hr><h2 id="_6-how-to-select-the-video-id-🔗" tabindex="-1">6. How to Select the Video ID 🔗 <a class="header-anchor" href="#_6-how-to-select-the-video-id-🔗" aria-label="Permalink to &quot;6. How to Select the Video ID 🔗&quot;">​</a></h2><p>Links can look very different. V-Train supports four types of IDs:</p><h3 id="📁-path-type" tabindex="-1">📁 Path Type <a class="header-anchor" href="#📁-path-type" aria-label="Permalink to &quot;📁 Path Type&quot;">​</a></h3><p>Link looks like this: <code>https://example.com/video/abc123/play</code></p><p>The ID is a part of the path. V-Train remembers which part you click.</p><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.mysite.com/watch/Xk9mP2q/</span></span>
<span class="line"><span>                              ↑</span></span>
<span class="line"><span>                        Click this part</span></span></code></pre></div><hr><h3 id="🔍-query-parameter-type" tabindex="-1">🔍 Query Parameter Type <a class="header-anchor" href="#🔍-query-parameter-type" aria-label="Permalink to &quot;🔍 Query Parameter Type&quot;">​</a></h3><p>Link looks like this: <code>https://example.com/watch?v=dQw4w9WgXcW&amp;t=30</code></p><p>The ID is after the <code>?</code>.</p><p><strong>Example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.youtube.com/watch?v=dQw4w9WgXcW</span></span>
<span class="line"><span>                                 ↑</span></span>
<span class="line"><span>                           Click this entire part</span></span></code></pre></div><hr><h3 id="️⃣-hash-type" tabindex="-1">#️⃣ Hash Type <a class="header-anchor" href="#️⃣-hash-type" aria-label="Permalink to &quot;#️⃣ Hash Type&quot;">​</a></h3><p>Link looks like this: <code>https://example.com/videos#ep-42</code></p><p>The ID is after the <code>#</code>.</p><hr><h3 id="✂️-separator-type" tabindex="-1">✂️ Separator Type <a class="header-anchor" href="#✂️-separator-type" aria-label="Permalink to &quot;✂️ Separator Type&quot;">​</a></h3><p>Sometimes the ID is mixed with other words.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/v/channel_abc123_hd</span></span>
<span class="line"><span>                               ↑</span></span>
<span class="line"><span>                    &quot;abc123&quot; is the real ID</span></span></code></pre></div><p>Select the whole part. Then, tell V-Train how to find the ID inside it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If the link is very difficult, check the <a href="https://github.com/vtrain-labs/community-rules" target="_blank" rel="noreferrer">Community Rules Library</a>. Someone else might have made the rule for you!</p></div><hr><h2 id="_7-using-the-four-save-slots-mod-1-mod-4-💾" tabindex="-1">7. Using the Four Save Slots (Mod 1 ~ Mod 4) 💾 <a class="header-anchor" href="#_7-using-the-four-save-slots-mod-1-mod-4-💾" aria-label="Permalink to &quot;7. Using the Four Save Slots (Mod 1 ~ Mod 4) 💾&quot;">​</a></h2><p>Every website has <strong>4 save slots</strong>. Why?</p><p>Because thumbnails look different on different pages:</p><table tabindex="0"><thead><tr><th>Save Slot</th><th>Use For</th></tr></thead><tbody><tr><td><strong>Mod 1</strong></td><td>Homepage thumbnails</td></tr><tr><td><strong>Mod 2</strong></td><td>Search page thumbnails</td></tr><tr><td><strong>Mod 3</strong></td><td>User Profile page thumbnails</td></tr><tr><td><strong>Mod 4</strong></td><td>Related video thumbnails</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Example</p><p>A website might have large pictures on the homepage and small pictures on the search page. You must train V-Train twice and save them in different slots.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If a slot already has a rule, saving will overwrite it. You cannot undo this. You can copy the old rule first to keep it safe.</p></div><hr><h2 id="_8-sharing-rules-vt-rule-📋" tabindex="-1">8. Sharing Rules (VT-RULE) 📋 <a class="header-anchor" href="#_8-sharing-rules-vt-rule-📋" aria-label="Permalink to &quot;8. Sharing Rules (VT-RULE) 📋&quot;">​</a></h2><p>Every rule has a <strong>serial number</strong>. It looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VT-RULE-Z... (followed by a long string)</span></span></code></pre></div><p>You can copy this text and share it with friends!</p><p><strong>How to get your rule serial:</strong></p><p>Open the V-Train Dashboard → Click &quot;Trained Sites (Rules)&quot; → Find the website → Click &quot;Share&quot;.</p><hr><h2 id="_9-community-rules-library-🌐" tabindex="-1">9. Community Rules Library 🌐 <a class="header-anchor" href="#_9-community-rules-library-🌐" aria-label="Permalink to &quot;9. Community Rules Library 🌐&quot;">​</a></h2><p>You do not have to train every website yourself. We have a Community Rules Library:</p><blockquote><p>🔗 <strong><a href="https://github.com/vtrain-labs/community-rules" target="_blank" rel="noreferrer">https://github.com/vtrain-labs/community-rules</a></strong></p></blockquote><p><strong>You can:</strong></p><ul><li>📥 <strong>Download rules</strong>: Find a website and copy the rule serial.</li><li>📤 <strong>Share rules</strong>: Share your rules to help other people.</li><li>⭐ <strong>Report problems</strong>: Tell people if a rule stops working.</li></ul><hr><h2 id="_10-training-faq-❓" tabindex="-1">10. Training FAQ ❓ <a class="header-anchor" href="#_10-training-faq-❓" aria-label="Permalink to &quot;10. Training FAQ ❓&quot;">​</a></h2><h3 id="q-i-right-clicked-but-start-training-engine-is-not-there" tabindex="-1">Q: I right-clicked, but &quot;Start Training Engine&quot; is not there? <a class="header-anchor" href="#q-i-right-clicked-but-start-training-engine-is-not-there" aria-label="Permalink to &quot;Q: I right-clicked, but &quot;Start Training Engine&quot; is not there?&quot;">​</a></h3><ol><li>Check if V-Train is turned on in Chrome (<code>chrome://extensions</code>).</li><li>Make sure you are on a real website (like <code>https://...</code>).</li><li>Refresh the page.</li><li>Make sure V-Train is in &quot;Monitoring&quot; mode.</li></ol><hr><h3 id="q-i-saved-the-rule-but-v-train-still-does-not-work" tabindex="-1">Q: I saved the rule, but V-Train still does not work? <a class="header-anchor" href="#q-i-saved-the-rule-but-v-train-still-does-not-work" aria-label="Permalink to &quot;Q: I saved the rule, but V-Train still does not work?&quot;">​</a></h3><ul><li><strong>You selected the wrong box</strong>: The rule is bad. Try training again and press <code>↑</code> or <code>↓</code> to select a different box.</li><li><strong>The website loads slowly</strong>: Wait for the page to finish loading completely.</li></ul><hr><h3 id="q-the-box-is-always-red-pressing-↑-does-not-work" tabindex="-1">Q: The box is always red. Pressing ↑ does not work? <a class="header-anchor" href="#q-the-box-is-always-red-pressing-↑-does-not-work" aria-label="Permalink to &quot;Q: The box is always red. Pressing ↑ does not work?&quot;">​</a></h3><p>Refresh the page. Right-click on a different part of the picture.</p><hr><h3 id="q-do-my-rules-sync-to-my-other-computer" tabindex="-1">Q: Do my rules sync to my other computer? <a class="header-anchor" href="#q-do-my-rules-sync-to-my-other-computer" aria-label="Permalink to &quot;Q: Do my rules sync to my other computer?&quot;">​</a></h3><p>No. Rules are saved <strong>only on this computer</strong>. You must copy the rule serials and send them to your other computer.</p><hr><h3 id="q-how-long-does-a-rule-take-to-work" tabindex="-1">Q: How long does a rule take to work? <a class="header-anchor" href="#q-how-long-does-a-rule-take-to-work" aria-label="Permalink to &quot;Q: How long does a rule take to work?&quot;">​</a></h3><p>It works immediately. Just refresh the page.</p>`,114)])])}const v=s(d,[["render",h]]);export{y as __pageData,v as default};
